import React from 'react';
import DataTable, {
  Table,
  TableBody,
  TableCell,
  TableContainer,
  TableHead,
  TableHeader,
  TableRow,
  TableSelectAll,
  TableSelectRow,
  TableBatchActions,
  TableBatchAction,
} from 'carbon-components-react';
import { Edit16, Reset16, Cancel16 } from '@carbon/icons-react';

const initialRows = [
  { id: 'a', name: 'Name 1' },
  { id: 'b', name: 'Name 2' },
];

const headers = [
  { key: 'name', header: 'Name' },
];

function App() {
  return (
    <DataTable
      rows={initialRows}
      headers={headers}
      render={({
        rows,
        headers,
        getHeaderProps,
        getSelectionProps,
        getBatchActionProps,
        selectedRows,
      }) => (
        <TableContainer title="DataTable with batch actions">
          <TableToolbar>
            <TableBatchActions {...getBatchActionProps()}>
              <TableBatchAction
                renderIcon={Edit16}
                iconDescription=""
                onClick={() => console.log('Edit action')}
              >
                Edit
              </TableBatchAction>
              <TableBatchAction
                renderIcon={Reset16}
                iconDescription=""
                onClick={() => console.log('Reset action')}
              >
                Reset
              </TableBatchAction>
              <TableBatchAction
                renderIcon={Cancel16}
                iconDescription=""
                onClick={() => console.log('Cancel action')}
              >
                Cancel
              </TableBatchAction>
            </TableBatchActions>
          </TableToolbar>
          <Table>
            <TableHead>
              <TableRow>
                <TableSelectAll {...getSelectionProps()} />
                {headers.map(header => (
                  <TableHeader {...getHeaderProps({ header })}>
                    {header.header}
                  </TableHeader>
                ))}
              </TableRow>
            </TableHead>
            <TableBody>
              {rows.map(row => (
                <TableRow key={row.id}>
                  <TableSelectRow {...getSelectionProps({ row })} />
                  {row.cells.map(cell => (
                    <TableCell key={cell.id}>{cell.value}</TableCell>
                  ))}
                </TableRow>
              ))}
            </TableBody>
          </Table>
        </TableContainer>
      )}
    />
  );
}

export default App;
